entries[108282] = { ["name"] = "Conductivity", ["text"] = "When you cast Healing Wave, Greater Healing Wave, Healing Surge, or Chain Heal, your Healing Rain's duration is increased by 4.00 sec.\n\nWhen you cast Lightning Bolt, Chain Lightning, [ Elemental Blast : Elemental Blast ]Earth Shock, or use Stormstrike, your Healing Rain's duration is increased by 4.00 sec.\n\nThis cannot cause Healing Rain to last longer than 40 sec." }
